CREATE TABLE model_routing_metadata_revisions(profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL CHECK(profile_revision>0),revision INTEGER NOT NULL CHECK(revision>0),metadata_json TEXT NOT NULL CHECK(json_valid(metadata_json)),created_at INTEGER NOT NULL CHECK(created_at>=0),PRIMARY KEY(profile_id,profile_revision,revision),FOREIGN KEY(profile_id,profile_revision)REFERENCES model_profile_revisions(profile_id,revision)ON DELETE RESTRICT)STRICT;
CREATE TABLE routing_health_observations(observation_id TEXT PRIMARY KEY,target_kind TEXT NOT NULL CHECK(target_kind IN('provider','model')),target_id TEXT NOT NULL,target_revision INTEGER NOT NULL CHECK(target_revision>0),state TEXT NOT NULL CHECK(state IN('healthy','degraded','unavailable')),latency_millis INTEGER NOT NULL CHECK(latency_millis>=0),observed_at INTEGER NOT NULL CHECK(observed_at>=0),expires_at INTEGER NOT NULL CHECK(expires_at>observed_at))STRICT;
CREATE INDEX routing_health_latest_idx ON routing_health_observations(target_kind,target_id,target_revision,observed_at DESC);
CREATE TABLE orchestration_budget_revisions(orchestration_id TEXT NOT NULL REFERENCES orchestrations(orchestration_id)ON DELETE CASCADE,revision INTEGER NOT NULL CHECK(revision>0),max_model_calls INTEGER NOT NULL CHECK(max_model_calls>0),max_input_tokens INTEGER NOT NULL CHECK(max_input_tokens>0),max_output_tokens INTEGER NOT NULL CHECK(max_output_tokens>0),max_remote_cost_micros INTEGER NOT NULL CHECK(max_remote_cost_micros>=0),max_concurrent_workers INTEGER NOT NULL CHECK(max_concurrent_workers>0),max_wall_time_millis INTEGER NOT NULL CHECK(max_wall_time_millis>0),window_started_at INTEGER NOT NULL CHECK(window_started_at>=0),created_at INTEGER NOT NULL CHECK(created_at>=window_started_at),PRIMARY KEY(orchestration_id,revision))STRICT;
CREATE TABLE routing_decisions(decision_id TEXT PRIMARY KEY,orchestration_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),task_node_id TEXT NOT NULL,budget_revision INTEGER NOT NULL CHECK(budget_revision>0),provider_id TEXT NOT NULL,provider_revision INTEGER NOT NULL CHECK(provider_revision>0),profile_id TEXT NOT NULL,profile_revision INTEGER NOT NULL CHECK(profile_revision>0),plan_json TEXT NOT NULL CHECK(json_valid(plan_json)),created_at INTEGER NOT NULL CHECK(created_at>=0),FOREIGN KEY(orchestration_id,graph_revision,task_node_id)REFERENCES orchestration_task_nodes(orchestration_id,graph_revision,task_node_id)ON DELETE RESTRICT,FOREIGN KEY(orchestration_id,budget_revision)REFERENCES orchestration_budget_revisions(orchestration_id,revision)ON DELETE RESTRICT,FOREIGN KEY(provider_id,provider_revision)REFERENCES model_provider_runtime_revisions(provider_id,revision)ON DELETE RESTRICT,FOREIGN KEY(profile_id,profile_revision)REFERENCES model_profile_revisions(profile_id,revision)ON DELETE RESTRICT)STRICT;
CREATE TABLE routing_budget_reservations(reservation_id TEXT PRIMARY KEY,decision_id TEXT NOT NULL UNIQUE REFERENCES routing_decisions(decision_id)ON DELETE RESTRICT,orchestration_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),task_node_id TEXT NOT NULL,reserved_calls INTEGER NOT NULL CHECK(reserved_calls>0),reserved_input_tokens INTEGER NOT NULL CHECK(reserved_input_tokens>0),reserved_output_tokens INTEGER NOT NULL CHECK(reserved_output_tokens>0),reserved_remote_cost_micros INTEGER NOT NULL CHECK(reserved_remote_cost_micros>=0),state TEXT NOT NULL CHECK(state IN('active','settled','released','overrun')),actual_calls INTEGER,actual_input_tokens INTEGER,actual_output_tokens INTEGER,actual_remote_cost_micros INTEGER,usage_complete INTEGER CHECK(usage_complete IS NULL OR usage_complete IN(0,1)),created_at INTEGER NOT NULL CHECK(created_at>=0),settled_at INTEGER,CHECK((state='active' AND settled_at IS NULL AND actual_calls IS NULL)OR(state<>'active' AND settled_at IS NOT NULL AND actual_calls IS NOT NULL)),FOREIGN KEY(orchestration_id,graph_revision,task_node_id)REFERENCES orchestration_task_nodes(orchestration_id,graph_revision,task_node_id)ON DELETE RESTRICT)STRICT;
CREATE UNIQUE INDEX routing_one_active_task_idx ON routing_budget_reservations(orchestration_id,graph_revision,task_node_id)WHERE state='active';
CREATE INDEX routing_budget_state_idx ON routing_budget_reservations(orchestration_id,state);
CREATE TABLE model_usage_records(usage_id TEXT PRIMARY KEY,reservation_id TEXT NOT NULL REFERENCES routing_budget_reservations(reservation_id)ON DELETE RESTRICT,resolved_model TEXT NOT NULL CHECK(length(resolved_model)BETWEEN 1 AND 256),input_tokens INTEGER,output_tokens INTEGER,remote_cost_micros INTEGER,usage_complete INTEGER NOT NULL CHECK(usage_complete IN(0,1)),occurred_at INTEGER NOT NULL CHECK(occurred_at>=0),CHECK(input_tokens IS NULL OR input_tokens>=0),CHECK(output_tokens IS NULL OR output_tokens>=0),CHECK(remote_cost_micros IS NULL OR remote_cost_micros>=0))STRICT;
CREATE INDEX model_usage_reservation_idx ON model_usage_records(reservation_id,occurred_at,usage_id);
